import WorkerPool from './worker-pool';
import type {WorkerPoolTarget} from './worker-pool';
import WorkerThread from './worker-thread';
import type {LoadWorker, WorkerJobMetrics} from '../../types';

/**
 * @param maxConcurrency - max count of workers
 * @param maxMobileConcurrency - max count of workers on mobile
 * @param maxConcurrency - max count of workers
 * @param reuseWorkers - if false, destroys workers when task is completed
 * @param onDebug - callback intended to allow application to log worker pool activity
 */
export type WorkerFarmProps = {
  maxQueuedJobs?: number;
  maxPendingAdmissions?: number;
  priorityAgingMs?: number;
  onMetrics?: (metrics: WorkerJobMetrics) => void;
  performanceMarks?: boolean;
  maxQueuedBytes?: number;
  maxInFlightBytes?: number;
  maxConcurrency?: number;
  maxMobileConcurrency?: number;
  reuseWorkers?: boolean;
  onDebug?: () => void;
};

const DEFAULT_PROPS: Required<WorkerFarmProps> = {
  maxQueuedJobs: Infinity,
  maxPendingAdmissions: 128,
  priorityAgingMs: 1000,
  onMetrics: () => {},
  performanceMarks: false,
  maxQueuedBytes: Infinity,
  maxInFlightBytes: Infinity,
  maxConcurrency: 3,
  maxMobileConcurrency: 1,
  reuseWorkers: true,
  onDebug: () => {}
};

/** Stable ids used to distinguish worker factories in the pool cache. */
const loadWorkerIds = new WeakMap<LoadWorker, number>();
/** Next stable worker-factory id. */
let nextLoadWorkerId = 1;

/**
 * Process multiple jobs with a "farm" of different workers in worker pools.
 */
export default class WorkerFarm {
  private props: WorkerFarmProps;
  private workerPools = new Map<string, WorkerPool>();
  // singleton
  private static _workerFarm?: WorkerFarm;

  /** Checks if workers are supported on this platform */
  static isSupported(): boolean {
    return WorkerThread.isSupported();
  }

  /** Get the singleton instance of the global worker farm */
  static getWorkerFarm(props: WorkerFarmProps = {}): WorkerFarm {
    WorkerFarm._workerFarm = WorkerFarm._workerFarm || new WorkerFarm({});
    WorkerFarm._workerFarm.setProps(props);
    return WorkerFarm._workerFarm;
  }

  /** get global instance with WorkerFarm.getWorkerFarm() */
  private constructor(props: WorkerFarmProps) {
    this.props = {...DEFAULT_PROPS};
    this.setProps(props);
    /** @type Map<string, WorkerPool>} */
    this.workerPools = new Map();
  }

  /**
   * Terminate all workers in the farm and abort active jobs.
   * @param reason Optional error delivered to active jobs.
   * @note Can free up significant memory
   */
  destroy(reason?: unknown): Promise<void> {
    const pools = [...this.workerPools.values()];
    this.workerPools.clear();
    return Promise.all(pools.map(pool => pool.destroy(reason))).then(() => undefined);
  }

  /**
   * Set props used when initializing worker pools
   * @param props
   */
  setProps(props: WorkerFarmProps): void {
    // Task payloads, signals and callbacks outside farm configuration must not be retained.
    const configuration: WorkerFarmProps = {};
    for (const key of Object.keys(DEFAULT_PROPS)) {
      if (props[key] !== undefined) configuration[key] = props[key];
    }
    this.props = {...this.props, ...configuration};
    // Update worker pool props
    for (const workerPool of this.workerPools.values()) {
      workerPool.setProps(this._getWorkerPoolProps());
    }
  }

  /**
   * Returns a worker pool for the specified worker
   * @param options Worker target used to identify and initialize the pool.
   * @param options.name Worker name used as the base pool identity.
   * @param options.url Worker script URL.
   * @param options.source Inline worker source.
   * @param options.loadWorker Built-in browser worker factory.
   * @example
   *   const job = WorkerFarm.getWorkerFarm().getWorkerPool({name, url}).startJob(...);
   */
  getWorkerPool(options: WorkerPoolTarget): WorkerPool {
    const {name, source, url, getUrl, loadWorker, workerType} = options;
    const workerPoolKey = getWorkerPoolKey(options);
    let workerPool = this.workerPools.get(workerPoolKey);
    if (!workerPool) {
      workerPool = new WorkerPool({
        name,
        source,
        url,
        getUrl,
        loadWorker,
        workerType
      });
      workerPool.setProps(this._getWorkerPoolProps());
      this.workerPools.set(workerPoolKey, workerPool);
    }
    return workerPool;
  }

  _getWorkerPoolProps() {
    return {
      maxQueuedJobs: this.props.maxQueuedJobs,
      maxPendingAdmissions: this.props.maxPendingAdmissions,
      priorityAgingMs: this.props.priorityAgingMs,
      onMetrics: this.props.onMetrics,
      performanceMarks: this.props.performanceMarks,
      maxQueuedBytes: this.props.maxQueuedBytes,
      maxInFlightBytes: this.props.maxInFlightBytes,
      maxConcurrency: this.props.maxConcurrency,
      maxMobileConcurrency: this.props.maxMobileConcurrency,
      reuseWorkers: this.props.reuseWorkers,
      onDebug: this.props.onDebug
    };
  }
}

/** Returns a cache key that distinguishes each worker source and factory. */
function getWorkerPoolKey(options: WorkerPoolTarget): string {
  const {name, source, url, urlKey, loadWorker, workerType} = options;
  const sourceKey = source ? `source:${source}` : '';
  const urlKeyPart = url || urlKey ? `url:${url || urlKey}` : '';
  const loadWorkerKey = loadWorker ? `loadWorker:${getLoadWorkerId(loadWorker)}` : '';
  return [name, sourceKey, urlKeyPart, loadWorkerKey, `type:${workerType || 'classic'}`]
    .filter(Boolean)
    .join('|');
}

/** Returns a stable identifier for a worker factory function. */
function getLoadWorkerId(loadWorker: LoadWorker): number {
  let loadWorkerId = loadWorkerIds.get(loadWorker);
  if (!loadWorkerId) {
    loadWorkerId = nextLoadWorkerId++;
    loadWorkerIds.set(loadWorker, loadWorkerId);
  }
  return loadWorkerId;
}
