import {NullLog} from '../log-utils/log';
import {
  canProcessOnWorker,
  canProcessOnWorkerInBatches,
  isBrowser,
  processOnWorker,
  processOnWorkerInBatches
} from '@loaders.gl/core/worker-utils';
import type {DataType} from '../../types';
import type {
  Loader,
  LoaderWithParser,
  StrictLoaderOptions,
  LoaderContext
} from '../../loader-types';

type ParseOnMainThread = (
  arrayBuffer: ArrayBuffer,
  loaders?: Loader | Loader[] | StrictLoaderOptions,
  options?: StrictLoaderOptions,
  context?: LoaderContext
) => Promise<unknown>;

/**
 * Determines if a loader can parse with worker
 * @param loader
 * @param options
 */
export function canParseWithWorker(loader: Loader, options?: StrictLoaderOptions) {
  // Caller-only loaders do not need worker transport or JSON-serializable limits.
  const workerUrl = (options?.[loader.id] as {workerUrl?: string} | undefined)?.workerUrl;
  if (options?.core?.worker === false || !(loader.worker || loader.loadWorker || workerUrl))
    return false;
  // Request signers and token providers cannot be cloned into worker runtimes.
  // Keep parsing on the caller so nested fetches retain these application callbacks.
  if (
    options?.core?.credentials?.some(
      credential =>
        credential.type === 'request' ||
        ('token' in credential && typeof credential.token === 'function')
    )
  )
    return false;
  // Multifile workers cannot transfer an application's custom fetch callback.
  if (loader.id === 'shapefile' && typeof options?.core?.fetch === 'function') return false;
  const workerOptions = getWorkerOptions(options);
  const nodeWorkers = workerOptions._nodeWorkers;
  if (!isBrowser && !nodeWorkers) {
    return false;
  }

  if (loader.id === 'csv' && !shouldParseCSVWithWorker(options)) {
    return false;
  }

  return Boolean(canProcessOnWorker(loader, workerOptions));
}

/**
 * Checks loader batch-parser transport capability and the selected worker's batch protocol.
 * @param loader Loader declaring compatible batch parsing and transport.
 * @param options Loader and worker selection options.
 */
export function canParseWithWorkerInBatches(
  loader: Loader,
  options?: StrictLoaderOptions
): boolean {
  // Encryption key callbacks must stay on the caller; JSON worker options omit functions.
  const parquetOptions = options?.parquet as {keyRetriever?: unknown} | undefined;
  if (loader.id === 'parquet' && typeof parquetOptions?.keyRetriever === 'function') {
    return false;
  }
  return Boolean(
    loader.workerInBatches &&
      canParseWithWorker(loader, options) &&
      canProcessOnWorkerInBatches(loader, getWorkerOptions(options))
  );
}

/**
 * Determines whether an atomic parse should use a worker, including optional loader work estimates.
 * @param loader Loader metadata or parser-bearing loader.
 * @param data Original parse input, before materialization.
 * @param options Loader and worker options.
 * @param context Loader context.
 * @param estimateLoader Optional metadata loader that owns the estimate hook.
 */
export function shouldParseWithWorker(
  loader: Loader,
  data: DataType,
  options?: StrictLoaderOptions,
  context?: LoaderContext,
  estimateLoader: Loader = loader
): boolean {
  if (!canParseWithWorker(loader, options)) {
    return false;
  }

  if (options?.core?.worker !== 'auto' || !estimateLoader.getWorkerEstimate) {
    return true;
  }

  try {
    const estimate = estimateLoader.getWorkerEstimate(data, options, context);
    if (estimate === undefined || !Number.isFinite(estimate) || estimate < 0 || estimate > 1) {
      return true;
    }
    return estimate >= (options.core?.workerThreshold ?? 0.1);
  } catch {
    // Estimation must never make a previously worker-capable parse fail.
    return true;
  }
}

/**
 * this function expects that the worker function sends certain messages,
 * this can be automated if the worker is wrapper by a call to createLoaderWorker in @loaders.gl/core/loader-utils.
 * @param loader Loader metadata used to select the worker pool.
 * @param data Input transferred to the worker.
 * @param options Loader and worker options.
 * @param context Serializable loader context.
 * @param parseOnMainThread Callback for worker requests that must run on the calling thread.
 * @param signal Optional cancellation signal for this worker job.
 */
export async function parseWithWorker(
  loader: Loader,
  data: any,
  options?: StrictLoaderOptions,
  context?: LoaderContext,
  parseOnMainThread?: ParseOnMainThread,
  signal?: AbortSignal
) {
  const workerSignal = signal || getWorkerAbortSignal(options) || context?.signal;
  const result = await processOnWorker(
    loader,
    data,
    {
      ...getWorkerOptions(options, loader),
      signal: workerSignal,
      onProgress: options?.onProgress || context?.reportProgress
    },
    {
      process: async (input, processOptions, workerContext, parseContext) => {
        if (!parseOnMainThread) {
          throw new Error('Worker not set up to parse on main thread');
        }
        const {_loaderIds, _loaderIsArray, ...workerParseContext} = parseContext || {};
        const mainThreadContext =
          context || parseContext || workerContext?.signal
            ? ({
                ...context,
                ...workerParseContext,
                signal: workerContext?.signal ?? context?.signal
              } as LoaderContext)
            : undefined;
        return await callParseOnMainThread(
          parseOnMainThread,
          input,
          processOptions,
          mainThreadContext,
          resolveWorkerLoaders(loader, _loaderIds, _loaderIsArray, context, options)
        );
      }
    },
    getSerializableLoaderContext(context)
  );
  return isLoaderWithWorkerResultDeserializer(loader)
    ? loader.deserializeWorkerResult(result, options, context)
    : result;
}

/**
 * Parses an input iterator through one stateful worker session.
 * @param loader Parser-bearing loader with a batched worker implementation.
 * @param inputIterator Input fragments to stream to the worker.
 * @param options Loader and worker options.
 * @param context Serializable loader context.
 * @param parseOnMainThread Callback for worker requests that must run on the calling thread.
 * @param signal Optional cancellation signal for this worker job.
 */
export async function* parseWithWorkerInBatches(
  loader: LoaderWithParser,
  inputIterator:
    | AsyncIterable<ArrayBufferLike | ArrayBufferView>
    | Iterable<ArrayBufferLike | ArrayBufferView>,
  options?: StrictLoaderOptions,
  context?: LoaderContext,
  parseOnMainThread?: ParseOnMainThread,
  signal?: AbortSignal
): AsyncIterable<unknown> {
  const workerSignal = signal || getWorkerAbortSignal(options) || context?.signal;
  const outputIterator = processOnWorkerInBatches(
    loader,
    inputIterator,
    {
      ...getWorkerOptions(options, loader),
      signal: workerSignal,
      onProgress: options?.onProgress || context?.reportProgress
    },
    {
      process: async (input, processOptions, workerContext, parseContext) => {
        if (!parseOnMainThread) {
          throw new Error('Worker not set up to parse on main thread');
        }
        const {_loaderIds, _loaderIsArray, ...workerParseContext} = parseContext || {};
        const mainThreadContext =
          context || parseContext || workerContext?.signal
            ? ({
                ...context,
                ...workerParseContext,
                signal: workerContext?.signal ?? context?.signal
              } as LoaderContext)
            : undefined;
        return await callParseOnMainThread(
          parseOnMainThread,
          input,
          processOptions,
          mainThreadContext,
          resolveWorkerLoaders(loader, _loaderIds, _loaderIsArray, context, options)
        );
      }
    },
    getSerializableLoaderContext(context)
  );

  for await (const batch of outputIterator) {
    yield loader.deserializeWorkerBatch
      ? loader.deserializeWorkerBatch(batch, options, context)
      : batch;
  }
}

/** Returns the loader-specific abort signal used to cancel a worker job. */
function getWorkerAbortSignal(options?: StrictLoaderOptions): AbortSignal | undefined {
  if (options?.signal) return options.signal;
  const parquetSignal = (options as {parquet?: {signal?: unknown}} | undefined)?.parquet?.signal;
  if (typeof AbortSignal !== 'undefined' && parquetSignal instanceof AbortSignal) {
    return parquetSignal;
  }
  return undefined;
}

/**
 * Calls either the legacy two-argument parse callback or the loader-utils callback.
 * @param parseOnMainThread Main-thread parse callback.
 * @param input Data to parse on the main thread.
 * @param options Loader options from the worker.
 * @param context Loader context merged from the worker and caller.
 * @param loaders Caller-local loaders selected by the worker.
 */
function callParseOnMainThread(
  parseOnMainThread: ParseOnMainThread,
  input: ArrayBuffer,
  options?: StrictLoaderOptions,
  context?: LoaderContext,
  loaders?: Loader | Loader[]
): Promise<unknown> {
  if (!loaders && parseOnMainThread.length <= 2) {
    return parseOnMainThread(input, options);
  }
  return parseOnMainThread(input, loaders, options, context);
}

/** Resolves worker-supplied loader identifiers to caller-local loaders without transferring functions. */
function resolveWorkerLoaders(
  loader: Loader,
  loaderIds: string[] | undefined,
  loaderIsArray: boolean | undefined,
  context?: LoaderContext,
  options?: StrictLoaderOptions
): Loader | Loader[] | undefined {
  if (!loaderIds) return undefined;
  const availableLoaders = new Map<string, Loader>();
  const visitedLoaders = new Set<Loader>();
  for (const candidate of [loader, ...(context?.loaders || [])]) {
    visitLoader(candidate);
  }
  const selectedLoaders = loaderIds.map(loaderId => {
    const selectedLoader = availableLoaders.get(loaderId);
    if (!selectedLoader) {
      throw new Error(
        `Worker requested unknown loader "${loaderId}". Declare it in loader.subloaders or pass it in context.loaders.`
      );
    }
    return selectedLoader;
  });
  return loaderIsArray ? selectedLoaders : selectedLoaders[0];

  /** Collects dependency metadata while retaining caller-provided parser implementations. */
  function visitLoader(candidate: Loader): void {
    if (visitedLoaders.has(candidate)) return;
    visitedLoaders.add(candidate);
    availableLoaders.set(candidate.id, candidate);
    for (const [name, dependency] of Object.entries(candidate.subloaders || {})) {
      const replacement = options?.core?.subloaders?.[name] || dependency;
      visitLoader(replacement);
      availableLoaders.set(dependency.id, replacement);
    }
  }
}

/**
 * Prepares worker routing controls and serializable parser options.
 * @param options
 * @param loader Loader whose parser will handle the worker request.
 */
function getWorkerOptions(options: StrictLoaderOptions = {}, loader?: Loader) {
  const portableOptions = loader?.serializeWorkerOptions?.(options) || options;
  const optionsToSerialize = {
    ...portableOptions,
    signal: undefined,
    onProgress: undefined,
    ...(portableOptions.core
      ? {
          core: {
            ...portableOptions.core,
            authentications: undefined,
            log: isDisabledLog(portableOptions.core.log) ? null : undefined
          }
        }
      : {})
  };
  const serializedOptions = JSON.parse(
    JSON.stringify(optionsToSerialize, (_key, value) => {
      if (typeof Headers !== 'undefined' && value instanceof Headers)
        return Object.fromEntries(value.entries());
      if (typeof AbortSignal !== 'undefined' && value instanceof AbortSignal) return undefined;
      return typeof value === 'bigint' ? null : value;
    })
  );
  restoreBigIntOptions(optionsToSerialize, serializedOptions);
  // The decision has already been made before dispatch.
  if (serializedOptions.core?.worker === 'auto') {
    serializedOptions.core.worker = true;
  }
  if (loader) {
    serializedOptions._workerLoaderId = loader.id;
  }
  return {
    ...serializedOptions,
    ...serializedOptions.core,
    parserOptions: serializedOptions
  };
}

/** Restores exact bigint leaves after JSON removes callbacks; ordinary JSON values keep their shape. */
function restoreBigIntOptions(original: any, serialized: any): void {
  if (!serialized || typeof serialized !== 'object') return;
  for (const key of Object.keys(serialized)) {
    const value = original?.[key];
    if (typeof value === 'bigint') serialized[key] = value;
    else restoreBigIntOptions(value, serialized[key]);
  }
}

/**
 * Create a serializable loader context for worker jobs.
 * @param context
 */
function getSerializableLoaderContext(context?: LoaderContext) {
  if (!context) {
    return {};
  }
  const {
    fetch,
    loaders,
    coreApi,
    signal,
    reportProgress,
    _parse,
    _parseSync,
    _parseInBatches,
    ...serializableContext
  } = context;
  return JSON.parse(JSON.stringify(serializableContext));
}

/**
 * Checks whether CSV options request Arrow output that can be transported from a worker.
 * @param options Loader options.
 * @returns True when CSV should parse on a worker.
 */
function shouldParseCSVWithWorker(options?: StrictLoaderOptions): boolean {
  const csvOptions = options as {csv?: {shape?: string}; core?: {shape?: string}} | undefined;
  return (csvOptions?.csv?.shape ?? csvOptions?.core?.shape) === 'arrow';
}

/**
 * Tests whether a loader can deserialize worker results.
 * @param loader Loader object.
 * @returns True when the loader exposes a worker result deserializer.
 */
function isLoaderWithWorkerResultDeserializer(
  loader: Loader
): loader is Loader & Required<Pick<Loader, 'deserializeWorkerResult'>> {
  return (
    typeof (loader as Loader & {deserializeWorkerResult?: unknown}).deserializeWorkerResult ===
    'function'
  );
}

/** Preserves explicit log suppression when crossing the worker boundary. */
function isDisabledLog(logger: unknown): boolean {
  return logger === null || logger instanceof NullLog;
}
