import type {Loader, LoaderContext, StrictLoaderOptions} from '@loaders.gl/core/loader-utils';
import {getFetchFunction} from './get-fetch-function';
import {extractQueryString, stripQueryString} from '../utils/url-utils';
import {path} from '@loaders.gl/core/loader-utils';
import {coreApi} from '../api/core-api';

/** Properties for creating an updated context */
type LoaderContextProps = Omit<LoaderContext, 'fetch' | 'coreApi'> &
  Partial<Pick<LoaderContext, 'fetch' | 'coreApi'>>;

/**
 * "sub" loaders invoked by other loaders get a "context" injected on `this`
 * The context will inject core methods like `parse` and contain information
 * about loaders and options passed in to the top-level `parse` call.
 *
 * @param context
 * @param options
 * @param parentContext
 */
export function getLoaderContext(
  context: LoaderContextProps,
  options: StrictLoaderOptions,
  parentContext: LoaderContext | null
): LoaderContext {
  // For recursive calls, preserve the context while applying this loader's options
  // TODO - add any additional loaders to context?
  if (parentContext) {
    return {
      ...parentContext,
      signal: options.signal || parentContext.signal,
      reportProgress: options.onProgress || parentContext.reportProgress,
      coreApi: parentContext.coreApi || context.coreApi || coreApi,
      _parse: parentContext._parse || context._parse,
      fetch: getFetchFunction(options, parentContext)
    };
  }

  const newContext: LoaderContext = {
    ...context,
    signal: options.signal || context.signal,
    reportProgress: options.onProgress || context.reportProgress,
    fetch: getFetchFunction(options, context),
    coreApi: context.coreApi || coreApi
  };

  // Parse URLs so that subloaders can easily generate correct strings
  if (newContext.url) {
    const baseUrl = stripQueryString(newContext.url);
    newContext.baseUrl = baseUrl;
    newContext.queryString = extractQueryString(newContext.url);
    newContext.filename = path.filename(baseUrl);
    newContext.baseUrl = path.dirname(baseUrl);
  }

  // Recursive loading does not use single loader
  if (!Array.isArray(newContext.loaders)) {
    newContext.loaders = null;
  }

  return newContext;
}

// eslint-disable-next-line complexity
export function getLoadersFromContext(
  loaders: Loader[] | Loader | undefined,
  context?: LoaderContext
): Loader | Loader[] | undefined {
  // A single loader (non-array) indicates no selection desired. Force select.
  if (loaders && !Array.isArray(loaders)) {
    return loaders;
  }

  // Create a merged list
  let candidateLoaders;
  if (loaders) {
    candidateLoaders = Array.isArray(loaders) ? loaders : [loaders];
  }
  if (context && context.loaders) {
    const contextLoaders = Array.isArray(context.loaders) ? context.loaders : [context.loaders];
    candidateLoaders = candidateLoaders ? [...candidateLoaders, ...contextLoaders] : contextLoaders;
  }
  // If no loaders, return null to look in globally registered loaders
  return candidateLoaders && candidateLoaders.length ? candidateLoaders : undefined;
}
